# Fixed
bars = [
    {'color': 3, 'col': 1, 'width': 4},
    {'color': 2, 'col': 2, 'width': 6},
    {'color': 3, 'col': 5, 'width': 4},
    {'color': 2, 'col': 5, 'width': 2},
    {'color': 3, 'col': 1, 'width': 2},
    {'color': 2, 'col': 4, 'width': 4}
]

# Col by color - properly built
col_by_color = {}
for b in bars:
    col = b['col']
    color = b['color']
    if col not in col_by_color:
        col_by_color[col] = {}
    if color not in col_by_color[col]:
        col_by_color[col][color] = 0
    col_by_color[col][color] += 1

print(f"Col by color: {col_by_color}")

# Starting columns (sorted): 1, 2, 4
# Count at first 3 columns
def count_at(bars, color, cols):
    return [col_by_color.get(c, {}).get(color, 0) for c in cols]

output = [
    count_at(bars, 3, [1, 2, 4]),  # color 3 at cols 1, 2, 4
    count_at(bars, 2, [1, 2, 4]),  # color 2 at cols 1, 2, 4
]
print(f"Output: {output}")

{"action": "submit", "grid": output}

